#!/usr/bin/env node
// npx @mozaik-ai/cloud-sdk pair — plain JS on purpose: npx runs this with
// node directly, so it cannot import the package's TypeScript sources.
import { chmodSync, mkdirSync, readFileSync, writeFileSync } from "node:fs"
import { homedir } from "node:os"
import { dirname, join } from "node:path"

const [, , command, ...rest] = process.argv
const endpointArg = rest.includes("--endpoint") ? rest[rest.indexOf("--endpoint") + 1] : undefined
const endpoint = (endpointArg ?? process.env.MOZAIK_CLOUD_ENDPOINT ?? "https://api.app.jigjoy.ai").replace(/\/$/, "")

if (command !== "pair") {
	console.log("mozaik cloud CLI")
	console.log("")
	console.log("  npx @mozaik-ai/cloud-sdk pair [--endpoint <url>]")
	console.log("    Connect this machine to your mozaik cloud project — approve in the")
	console.log("    browser, the key is cached in ~/.mozaik/credentials.json.")
	process.exit(command ? 1 : 0)
}

const startRes = await fetch(`${endpoint}/v1/pair/start`, { method: "POST" })
if (startRes.status !== 201) {
	console.error(`pairing start failed: ${startRes.status} ${await startRes.text()}`)
	process.exit(1)
}
const start = await startRes.json()

console.log("")
console.log("▶ mozaik cloud — pair this machine")
console.log(`  code:    ${start.code}`)
console.log(`  approve: ${start.approveUrl}`)
console.log("  waiting for approval… (Ctrl+C to abort)")

const interval = Math.max(1000, (start.pollIntervalSeconds ?? 3) * 1000)
const deadline = Date.now() + (start.expiresInSeconds ?? 600) * 1000
for (;;) {
	if (Date.now() > deadline) {
		console.error("pairing timed out — run it again and approve within 10 minutes")
		process.exit(1)
	}
	await new Promise((r) => setTimeout(r, interval))
	const res = await fetch(`${endpoint}/v1/pair/poll?code=${encodeURIComponent(start.code)}&secret=${encodeURIComponent(start.pollSecret)}`)
	if (res.status === 404 || res.status === 410) {
		console.error("pairing code expired — run it again and approve within 10 minutes")
		process.exit(1)
	}
	if (!res.ok) {
		// transient errors are retried, but never silently forever
		globalThis.__pairErrs = (globalThis.__pairErrs ?? 0) + 1
		if (globalThis.__pairErrs >= 5) {
			console.error(`pairing failed: server keeps answering ${res.status} — ${(await res.text()).slice(0, 200)}`)
			process.exit(1)
		}
		continue
	}
	globalThis.__pairErrs = 0
	const body = await res.json()
	if (body.status !== "claimed" || !body.projectKey) continue

	const file = process.env.MOZAIK_CREDENTIALS_FILE ?? join(homedir(), ".mozaik", "credentials.json")
	let all = {}
	try {
		all = JSON.parse(readFileSync(file, "utf8"))
	} catch {
		// first pairing on this machine
	}
	all[endpoint] = { projectKey: body.projectKey, projectId: body.projectId, name: body.name, pairedAt: new Date().toISOString() }
	mkdirSync(dirname(file), { recursive: true })
	writeFileSync(file, JSON.stringify(all, null, 2) + "\n")
	try {
		chmodSync(file, 0o600)
	} catch {
		// best-effort
	}
	console.log(`✓ paired with project "${body.name ?? body.projectId}" — credentials cached, no .env needed`)
	process.exit(0)
}
